declarationBytesAndDependencyClosure.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';import assert from 'node:assert/strict';import {spawnSync,execFileSync} from 'node:child_process';
const base='f4ec0f7c646f9e996381b855fc469151c466fb32';
const original=['recording_catalog.h','recording_read_service.h','recording_derived_selection.h','recording_derived_remux.h'].map(name=>execFileSync('git',['show',base+':include/recording/'+name],{encoding:'utf8'})).join('\n');
const definition=(text,name)=>{const start=text.search(new RegExp('(?:struct|enum class) '+name+' \\{'));assert(start>=0,name);let level=0,end=start;for(;end<text.length;end++){if(text[end]==='{')level++;if(text[end]==='}'&&--level===0)break;}return text.slice(start,end+2);};
let count=0;
for(const name of ['recording_query_values.h','recording_selection_values.h','recording_remux_result.h']){
 const file='include/recording/'+name,text=fs.readFileSync(file,'utf8');
 for(const match of text.matchAll(/(?:struct|enum class) (\w+) \{/g)){assert.equal(definition(text,match[1]),definition(original,match[1]),match[1]);count++;}
}
for(const file of ['src/recording/recording_derived_job_context.h','include/recording/recording_remux_result.h']){
 const r=spawnSync('c++',['-std=c++17','-Iinclude','-iquote','.','-MM','-x','c++','-'],{input:'#include "'+file+'"\n',encoding:'utf8'});
