 console.log('[dependency] '+file+' no selection/remux execution or analysis/read-service declarations');
}
console.log('[declarations] '+count+' moved definitions byte-identical to '+base);
console.log('[scope] no ABI/runtime equivalence claim; algorithm .cpp implementation unchanged');
